WHERE "Name of ICI" = 'Atezolizumab+Trastuzumab emtansine+Placebo' AND "Cancer type" = 'Hodgkin Lymphoma'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_trial_acronym(source_value) AS "trial_acronym"
FROM base;

